function processBatch(messages) {
  for (const msg of messages) {
    if (!msg.payload) {
      log.warn("skip empty");
      continue;
    }
    if (msg.poison) {
      log.error("poison");
      continue;
    }
    handle(msg);
  }
}

function parseToken(raw) {
  if (!raw) return null;
  if (raw.length < 10) return null;
  return decode(raw);
}

switch (code) {
