const matrix = [[1, 2], [3, 4]];
let target = 3;
let coords = null;

outer: for (let r = 0; r < matrix.length; r++) {
  for (let c = 0; c < matrix[r].length; c++) {
    if (matrix[r][c] === target) {
      coords = { r, c };
      break outer;
    }
  }
}

